test_that("run_pipeline numbers its steps and ends with a summary box", {
  vis <- NULL
  out <- cli::cli_fmt(vis <- withVisible(run_pipeline(nedap, verbose = 1)))
  expect_false(vis$visible)
  expect_true(all(sprintf("[%d/6]", 1:6) %in% regmatches(out, regexpr("\\[[0-9]/6\\]", out))))
  expect_true(any(grepl("Results NEDAP", out, fixed = TRUE)))
  expect_true(any(grepl("31,863", out, fixed = TRUE)))
  # the counter is reset afterwards: a single step is not numbered
  one <- cli::cli_fmt(prep_visits(nedap, verbose = 1))
  expect_false(any(grepl("[1/6]", one, fixed = TRUE)))
  expect_true(withVisible(run_pipeline(nedap, verbose = 0))$visible)
})

test_that("count rows are aligned and zeros are hidden", {
  withr::local_options(tidypptsda.verbose = 1L)
  rows <- function() ppt_rows(ppt_row("Records", 12345, keep = TRUE),
                              ppt_row("zero", 0, of = 12345, depth = 1L),
                              ppt_row("few", 1, of = 12345, depth = 1L, warn = TRUE),
                              ppt_row("skipped", NA))
  x <- cli::ansi_strip(cli::cli_fmt(rows()))
  expect_length(x, 2L)
  expect_match(x[1], "Records +12,345$")
  expect_match(x[2], "few +1 +<0.1%$")
  # numbers are right-aligned: they end in the same column
  expect_equal(as.integer(regexpr("12,345", x[1])) + 5L, as.integer(regexpr(" 1 ", x[2])) + 1L)
  withr::local_options(tidypptsda.verbose = 2L)
  expect_length(cli::cli_fmt(rows()), 3L)
  expect_equal(fmt_n(1234567), "1,234,567")
})

test_that("every pig is either analysed or listed with a reason", {
  for (data in list(nedap, fire)) {
    for (q in list(qc_config(), qc_config(impute_method = "linear", curve_model = "poly3"))) {
      res <- suppressWarnings(run_pipeline(data, qc = q, verbose = 0))
      expect_s3_class(res, "ppt_pipeline")
      ids <- unique(stats::na.omit(res$visits$responder))
      with_fcr <- res$fcr$per_pig[!is.na(fcr), responder]
      expect_setequal(union(with_fcr, res$removed$responder), ids)
      expect_true(all(nzchar(res$removed$reason)))
      # each step works on a subset of the previous one
      expect_true(all(res$adg$per_pig$responder %in% res$weight$per_pig$responder))
      expect_true(all(res$fcr$per_pig$responder %in% res$adg$per_pig$responder))
    }
  }
})

test_that("pipeline equals running the steps one by one", {
  qc <- qc_config()
  res <- run_pipeline(nedap, qc = qc, verbose = 0)
  v <- prep_visits(nedap, qc = qc, verbose = 0)
  a <- calc_adg(clean_weight(v, qc, verbose = 0), verbose = 0)
  f <- calc_fcr(a, calc_adfi(v, a, verbose = 0), verbose = 0)
  expect_equal(res$fcr$per_pig, f$per_pig)
})

test_that("print method runs and verbose = 0 is silent", {
  expect_silent(res <- run_pipeline(fire, verbose = 0))
  expect_message(print(res), "FCR")
})
